const ssh = $input.first().json;
if (ssh.code !== 0) throw new Error('Backup SSH command failed; inspect execution and target status');
let result;
try { result = JSON.parse(ssh.stdout); } catch { throw new Error('Backup returned invalid JSON'); }
if (result.status !== 'success') throw new Error('Backup failed; inspect target status');
return [{ json: result }];

const result = $input.first().json;
if (result.status !== 'success') throw new Error('Backup did not complete successfully');
const clean = value => String(value ?? '').replace(/[\r\n\x00-\x1f]/g, ' ').replace(/@/g, '＠').replace(/[`*_~|<>]/g, '').slice(0, 100);
const html = value => String(value).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const bytes = value => {
  if (!Number.isFinite(value) || value < 0) return 'unknown';
  const units = ['B', 'KiB', 'MiB', 'GiB', 'TiB'];
  const index = Math.min(Math.floor(Math.log(Math.max(value, 1)) / Math.log(1024)), units.length - 1);
  return (value / 1024 ** index).toFixed(index ? 1 : 0) + ' ' + units[index];
};
const apps = Array.isArray(result.apps) ? result.apps : [];
const saved = apps.filter(app => !app.unchanged);
const uploaded = bytes(saved.reduce((sum, app) => sum + app.data_added, 0));
const server = clean(result.server_id);
const description = saved.length + ' saved · ' + (apps.length - saved.length) + ' unchanged';
const appLines = apps.slice(0, 7).map(app => clean(app.id).slice(0, 50) + ' · ' + (app.unchanged ? 'unchanged' : bytes(app.data_added)) + '\n' + clean(app.archive).slice(0, 80));
if (apps.length > 7) appLines.push('+ ' + (apps.length - 7) + ' more in the execution');
const timestamp = new Date(result.finished).toISOString();
const title = '✓ Backup complete';
const fields = [
  { name: 'Server', value: server, inline: true },
  { name: 'Uploaded', value: uploaded, inline: true },
];
if (appLines.length) fields.push({ name: 'Applications', value: appLines.join('\n'), inline: false });
const discordEmbed = { title, description, color: 3066993, fields,
  footer: { text: 'VPS Backup · Run #' + clean($execution.id) }, timestamp };
const telegramMessage = ['<b>' + title + '</b>', '<code>' + html(server) + '</code>',
  '', html(description), '<b>Uploaded</b>  ' + uploaded,
  '<pre>' + html(appLines.join('\n')) + '</pre>',
  '<i>' + html(timestamp) + ' · Run #' + html(clean($execution.id)) + '</i>'].join('\n');
return [{ json: { discordEmbed, telegramMessage, server_id: result.server_id } }];
